<template>
  <section class="attendance-report">
    <form class="attendance-filters" @submit.prevent="load">
      <label>{{ tr('Desde','From') }}<input v-model="from" type="date" required class="form-control" /></label>
      <label>{{ tr('Hasta','To') }}<input v-model="to" type="date" required :min="from" class="form-control" /></label>
      <label>{{ tr('Miembro','Member') }}<select v-model="member" class="form-select"><option value="">{{ tr('Todos los miembros','All members') }}</option><option v-for="person in people" :key="person.id" :value="String(person.id)">{{ person.name }}</option></select></label>
      <label>{{ tr('Tipo de servicio','Service type') }}<select v-model="service" class="form-select"><option value="">{{ tr('Todos los servicios','All services') }}</option><option value="legacy">{{ tr('Registros diarios anteriores','Legacy daily records') }}</option><option v-for="s in services" :key="s.id" :value="String(s.id)">{{ s.name }}</option></select><small>{{ tr('Por ejemplo: Escuela Sabática, en todo el período.','For example: Sabbath School throughout the date range.') }}</small></label>
      <label>{{ tr('Servicio en una fecha','Service on a specific date') }}<select v-model="session" class="form-select"><option value="">{{ tr('Todas las fechas del período','All dates in the range') }}</option><option v-for="s in sessions" :key="s.id" :value="String(s.id)">{{ s.service_date }} · {{ s.name }}</option></select><small>{{ tr('Opcional: elige un solo servicio de un día concreto.','Optional: choose one service on one specific day.') }}</small></label>
      <button class="btn btn-primary"  :disabled="loading">{{ loading ? tr('Cargando…','Loading…') : tr('Consultar','View report') }}</button>
    </form>
    <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p>
    <template v-if="report">
      <p class="report-period">{{ applied.from }} — {{ applied.to }} · {{ applied.name }}</p>
      <div class="attendance-stats"><article><span>{{ tr('Asistencias registradas','Recorded check-ins') }}</span><strong>{{ report.summary.check_ins }}</strong></article><article><span>{{ tr('Miembros distintos','Unique members') }}</span><strong>{{ report.summary.members }}</strong></article><article><span>{{ tr('Días con registros','Days with records') }}</span><strong>{{ report.summary.recorded_days }}</strong></article></div>
      <section class="attendance-chart">
        <header><div><h2>{{ chartTitle }}</h2><p>{{ chartPeriod }}</p><p>{{ tr('Un registro por persona y servicio. Cero no confirma ausencia.','One record per person per service. Zero does not confirm absence.') }}</p></div><label>{{ tr('Agrupar por','Group by') }}<select v-model="grouping" class="form-select"><option value="day">{{ tr('Día','Day') }}</option><option value="week">{{ tr('Semana','Week') }}</option><option value="month">{{ tr('Mes','Month') }}</option></select></label></header>
        <p v-if="!bars.length" class="attendance-empty">{{ tr('No hay servicios ni asistencias registradas en este período.','No services or attendance recorded in this period.') }}</p>
        <div v-else class="line-chart" role="group" :aria-label="tr('Gráfico de asistencia por fecha','Attendance chart by date')">
          <AttendanceLineChart :points="bars" :series="chartSeries" :selected="selected" :label="tr('Asistencias','Check-ins')" @select="selected=selected===$event?'':$event" />
          <div class="chart-values"><button v-for="point in bars" :key="point.date" type="button" :class="{selected:selected===point.date}" :aria-pressed="selected===point.date" @click="selected=selected===point.date?'':point.date"><span>{{ point.date }}</span><strong>{{ point.count }}</strong></button></div>
        </div>
        <p v-if="bars.length" class="chart-hint">{{ tr('Selecciona una fecha para ver sus registros.','Select a date to see its records.') }}</p>
      </section>
      <section class="attendance-details"><header><h2>{{ tr('Detalle de asistencia','Attendance details') }} <small>({{ filtered.length }})</small></h2><button v-if="selected" type="button" class="btn btn-outline-secondary" @click="selected=''">{{ tr('Ver todo el período','Show entire period') }}</button></header>
        <div v-for="record in pageRecords" :key="`${record.date}-${record.member_id}-${record.session_id}`" class="attendance-record"><time :datetime="record.date">{{ record.date }}</time><span>{{ record.name }}<small class="d-block">{{ record.service_name || tr('Registro diario anterior','Legacy daily record') }}</small></span><span class="present-badge">{{ tr('Presente','Present') }}</span></div>
        <p v-if="!filtered.length" class="attendance-empty">{{ tr('Sin registros.','No records.') }}</p>
        <nav v-if="filtered.length>25" class="attendance-pagination" :aria-label="tr('Páginas de registros','Record pages')"><button type="button" class="btn btn-outline-secondary" :disabled="page===1" @click="page--">{{ tr('Anterior','Previous') }}</button><span>{{ page }} / {{ Math.ceil(filtered.length/25) }}</span><button type="button" class="btn btn-outline-secondary" :disabled="page*25>=filtered.length" @click="page++">{{ tr('Siguiente','Next') }}</button></nav>
      </section>
    </template>
  </section>
</template>
<script setup>
import { ref,computed,onMounted,watch,onUnmounted } from 'vue'
import AttendanceLineChart from './AttendanceLineChart.vue'
import { apiClient } from '../services/authApi'
import { useUiStore } from '../stores/uiStore'
const ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`
const service=ref(''),session=ref(''),services=ref([]),sessions=ref([])
const today=new Date(),from=ref(localDate(new Date(today.getFullYear(),today.getMonth(),1))),to=ref(localDate(today)),member=ref(''),people=ref([]),report=ref(null),applied=ref({}),error=ref(''),loading=ref(false),grouping=ref('day'),selected=ref(''),page=ref(1)
watch([service,from,to],()=>session.value='')
let version=0
function bucket(date){if(grouping.value==='month')return date.slice(0,7);if(grouping.value==='week'){const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()-(d.getDay()+6)%7);return localDate(d)}return date}
const bars=computed(()=>{const groups=new Map();for(const s of report.value?.sessions||[]){if(applied.value.legacy)continue;if(applied.value.service_id&&String(s.attendance_service_id)!==String(applied.value.service_id))continue;if(applied.value.session_id&&String(s.id)!==String(applied.value.session_id))continue;const key=bucket(String(s.service_date).slice(0,10));if(!groups.has(key))groups.set(key,0)}for(const row of report.value?.records||[]){const key=bucket(String(row.date).slice(0,10));groups.set(key,(groups.get(key)||0)+1)}return [...groups].sort(([a],[b])=>a.localeCompare(b)).map(([date,count])=>({date,count}))})
const chartTitle=computed(()=>{const item=report.value?.sessions?.find(s=>String(s.id)===String(applied.value.session_id));const svc=report.value?.services?.find(s=>String(s.id)===String(applied.value.service_id));return item?.name||svc?.name||(applied.value.legacy?tr('Registros diarios anteriores','Legacy daily records'):tr('Todos los servicios','All services'))})
const chartPeriod=computed(()=>{const item=report.value?.sessions?.find(s=>String(s.id)===String(applied.value.session_id));if(item)return String(item.service_date).slice(0,10);return applied.value.from===applied.value.to?applied.value.from:`${applied.value.from} — ${applied.value.to}`})
const chartSeries=computed(()=>{const groups=new Map();const keyFor=(id,name)=>id!=null?`service:${id}`:name?`session:${name}`:'legacy';const ensure=(id,name)=>{const key=keyFor(id,name);if(!groups.has(key))groups.set(key,{key,label:name||tr('Registros diarios anteriores','Legacy daily records'),counts:new Map()});return groups.get(key)};for(const s of report.value?.sessions||[]){if(applied.value.legacy||applied.value.service_id&&String(s.attendance_service_id)!==String(applied.value.service_id)||applied.value.session_id&&String(s.id)!==String(applied.value.session_id))continue;const svc=report.value?.services?.find(v=>String(v.id)===String(s.attendance_service_id));const g=ensure(s.attendance_service_id,svc?.name||s.name);const date=bucket(String(s.service_date).slice(0,10));if(!g.counts.has(date))g.counts.set(date,0)}for(const r of report.value?.records||[]){const svc=report.value?.services?.find(v=>String(v.id)===String(r.service_id));const g=ensure(r.service_id,svc?.name||r.service_name);const date=bucket(String(r.date).slice(0,10));g.counts.set(date,(g.counts.get(date)||0)+1)}return [...groups.values()].sort((a,b)=>a.label.localeCompare(b.label)).map(g=>({key:g.key,label:g.label,values:bars.value.map(b=>g.counts.has(b.date)?g.counts.get(b.date):null)}))})
const filtered=computed(()=>(report.value?.records||[]).filter(r=>!selected.value||bucket(r.date)===selected.value))
const pageRecords=computed(()=>filtered.value.slice((page.value-1)*25,page.value*25))
watch(grouping,()=>{selected.value=''});watch(selected,()=>{page.value=1})
async function load(){const current=++version;loading.value=true;error.value='';report.value=null;selected.value='';page.value=1;const params={from:from.value,to:to.value,member_id:member.value||undefined,service_id:service.value&&service.value!=='legacy'?service.value:undefined,legacy:service.value==='legacy'?true:undefined,session_id:session.value||undefined};try{const {data}=await apiClient.get('/reports/attendance',{params});if(current!==version)return;people.value=data.members;services.value=data.services;sessions.value=data.sessions;report.value=data;applied.value={...params,name:params.member_id?data.members.find(m=>String(m.id)===params.member_id)?.name:tr('Todos los miembros','All members')};grouping.value=data.series.length>62?'month':data.series.length>31?'week':'day'}catch(e){if(current===version)error.value=Object.values(e.response?.data?.errors||{}).flat().join(' ')||tr('No se pudo cargar el reporte.','Unable to load the report.')}finally{if(current===version)loading.value=false}}
onMounted(load);onUnmounted(()=>{version++})
</script>
<style scoped>
.attendance-report{min-width:0;display:grid;gap:18px}.attendance-filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;align-items:end;background:#f8faf9;padding:18px;border:1px solid #dce5de;border-radius:10px}.attendance-filters label,.attendance-chart label{min-width:0;font-size:12px;color:#53665b}.attendance-filters input,.attendance-filters select,.attendance-chart select{margin-top:6px;font-size:13px;min-width:0;width:100%}.attendance-report .btn{width:auto;white-space:normal}.attendance-report .btn-primary{background:#1f6f5c;color:white;border-color:#1f6f5c}.attendance-report .btn-outline-secondary{background:white;color:#405f50;border-color:#9eb3a5}.attendance-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.attendance-stats article{background:white;border:1px solid #dce5de;border-radius:9px;padding:16px;display:grid;gap:6px}.attendance-stats span{font-size:12px;color:#64746b}.attendance-stats strong{font-size:24px;font-weight:500;color:#24523c}.attendance-chart,.attendance-details{background:white;border:1px solid #dce5de;border-radius:10px;padding:20px;min-width:0}.attendance-report header{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:18px}.attendance-report h2{font-size:16px;font-weight:500;margin:0 0 6px}.attendance-report p,.attendance-report small{font-size:12px;color:#617268}.bar-chart{display:grid;gap:6px;max-height:420px;overflow-y:auto}.bar-row{display:grid;grid-template-columns:90px minmax(0,1fr) 40px;align-items:center;gap:12px;width:100%;padding:8px;border:1px solid transparent;border-radius:6px;background:white;color:#3b5748;text-align:left;font-size:12px}.bar-row:hover,.bar-row.selected{background:#edf5ef;border-color:#aecabb}.bar-row strong{text-align:right;font-weight:500}.bar-track{height:20px;background:#f0f4f1;border-radius:4px;overflow:hidden}.bar-track>span{display:block;height:100%;background:#348364;border-radius:4px;min-width:0}.attendance-record{display:grid;grid-template-columns:100px minmax(0,1fr) auto;gap:12px;padding:12px 0;border-bottom:1px solid #e9eee9;font-size:13px;overflow-wrap:anywhere}.present-badge{background:#edf5ef;color:#245e42;border-radius:14px;padding:3px 8px;font-size:11px;align-self:start}.attendance-empty{text-align:center;padding:26px 0}.attendance-pagination{display:flex;justify-content:center;align-items:center;gap:14px;margin-top:18px}.chart-hint{margin:14px 0 0}.report-period{margin:0}@media(max-width:650px){.attendance-filters{grid-template-columns:1fr 1fr;padding:14px}.attendance-filters>label:nth-child(3){grid-column:1/-1}.attendance-stats{grid-template-columns:1fr}.attendance-stats article{display:flex;justify-content:space-between;align-items:center}.attendance-chart,.attendance-details{padding:14px}.attendance-record{grid-template-columns:1fr auto}.attendance-record time{grid-column:1/-1;color:#68786e}.bar-row{grid-template-columns:80px minmax(0,1fr) 28px;gap:7px;padding:8px 3px}}
.attendance-filters small{display:block;margin-top:6px;color:#52645a;font-size:.75rem;line-height:1.4;font-weight:400}
.line-chart svg{width:100%;height:240px;display:block;overflow:visible}.chart-axis{stroke:#b7c9be;stroke-width:1.5}.chart-line{fill:none;stroke:#1f795a;stroke-width:3;vector-effect:non-scaling-stroke}.chart-dot{fill:#fff;stroke:#1f795a;stroke-width:3;vector-effect:non-scaling-stroke}.chart-values{display:flex;gap:8px;overflow-x:auto;padding:8px 0}.chart-values button{flex:1 0 auto;min-width:78px;padding:7px;border:1px solid #dce5de;border-radius:6px;background:#fff;color:#355848;display:grid;gap:3px;font-size:12px}.chart-values button:hover,.chart-values button.selected{background:#e8f4ec;border-color:#4c9272}.chart-values strong{font-size:14px}
.chart-label{fill:#355848;font-size:14px;font-weight:600}
</style>
